const listContractInstances = `-- name: ListContractInstances :many
SELECT id, uuid, organization_id, brand_id, contract_no, subject_type, subject_id, subject_service_id, template_id, kind, locale, template_version, otp_required, signature_required, status, rendered_html, content_sha256, pdf_key, executed_at, voided_at, void_reason, voided_by_user_id, created_by_user_id, created_at, updated_at FROM contract_instances
WHERE organization_id = ANY($1::bigint[])
  AND ($2::text IS NULL OR status = $2::text)
  AND ($3::text IS NULL OR kind = $3::text)
ORDER BY created_at DESC, id DESC
LIMIT $5::int OFFSET $4::int
`

type ListContractInstancesParams struct {
	OrgIds    []int64     `json:"org_ids"`
	Status    pgtype.Text `json:"status"`
	Kind      pgtype.Text `json:"kind"`
	RowOffset int32       `json:"row_offset"`
	RowLimit  int32       `json:"row_limit"`
}

// org_ids is the caller's scope (empty = no organization).
func (q *Queries) ListContractInstances(ctx context.Context, arg ListContractInstancesParams) ([]ContractInstance, error) {
	rows, err := q.db.Query(ctx, listContractInstances,
		arg.OrgIds,
		arg.Status,
		arg.Kind,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ContractInstance{}
	for rows.Next() {
		var i ContractInstance
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.BrandID,
			&i.ContractNo,
			&i.SubjectType,
			&i.SubjectID,
			&i.SubjectServiceID,
			&i.TemplateID,
			&i.Kind,
			&i.Locale,
			&i.TemplateVersion,
			&i.OtpRequired,
			&i.SignatureRequired,
			&i.Status,
			&i.RenderedHtml,
			&i.ContentSha256,
			&i.PdfKey,
			&i.ExecutedAt,
			&i.VoidedAt,
			&i.VoidReason,
			&i.VoidedByUserID,
			&i.CreatedByUserID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

