const upsertContractSigner = `-- name: UpsertContractSigner :one

INSERT INTO contract_signers (
    instance_id, organization_id, brand_id, role, user_id, name, phone_e164
)
VALUES (
    $1, $2, $3, $4,
    $5, $6, $7
)
ON CONFLICT (instance_id, role) DO UPDATE
SET user_id = EXCLUDED.user_id,
    name = EXCLUDED.name,
    phone_e164 = EXCLUDED.phone_e164,
    otp_code_id = CASE
        WHEN contract_signers.user_id IS NOT DISTINCT FROM EXCLUDED.user_id
         AND contract_signers.phone_e164 IS NOT DISTINCT FROM EXCLUDED.phone_e164
        THEN contract_signers.otp_code_id END,
    otp_verified_at = CASE
        WHEN contract_signers.user_id IS NOT DISTINCT FROM EXCLUDED.user_id
         AND contract_signers.phone_e164 IS NOT DISTINCT FROM EXCLUDED.phone_e164
        THEN contract_signers.otp_verified_at END,
    signed_at = CASE
        WHEN contract_signers.user_id IS NOT DISTINCT FROM EXCLUDED.user_id
         AND contract_signers.phone_e164 IS NOT DISTINCT FROM EXCLUDED.phone_e164
        THEN contract_signers.signed_at END
RETURNING id, uuid, instance_id, organization_id, brand_id, role, user_id, name, phone_e164, otp_code_id, otp_verified_at, signed_at, created_at, updated_at
`

type UpsertContractSignerParams struct {
	InstanceID     int64       `json:"instance_id"`
	OrganizationID int64       `json:"organization_id"`
	BrandID        int64       `json:"brand_id"`
	Role           string      `json:"role"`
	UserID         pgtype.Int8 `json:"user_id"`
	Name           string      `json:"name"`
	PhoneE164      pgtype.Text `json:"phone_e164"`
}

// ---------------------------------------------------------------------------
// Signers.
// Fills the customer or staff slot of an open contract; a changed person
// clears the OTP proof and the signed time.
func (q *Queries) UpsertContractSigner(ctx context.Context, arg UpsertContractSignerParams) (ContractSigner, error) {
	row := q.db.QueryRow(ctx, upsertContractSigner,
		arg.InstanceID,
		arg.OrganizationID,
		arg.BrandID,
		arg.Role,
		arg.UserID,
		arg.Name,
		arg.PhoneE164,
	)
	var i ContractSigner
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.InstanceID,
		&i.OrganizationID,
		&i.BrandID,
		&i.Role,
		&i.UserID,
		&i.Name,
		&i.PhoneE164,
		&i.OtpCodeID,
		&i.OtpVerifiedAt,
		&i.SignedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

